// Funções auxiliares para geração de payload PIX válido com CRC16 (Padrão EMV / Banco Central)
function calculateCRC16(payload: string): string {
  let crc = 0xFFFF;
  for (let i = 0; i < payload.length; i++) {
    crc ^= payload.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++) {
      if ((crc & 0x8000) !== 0) {
        crc = (crc << 1) ^ 0x1021;
      } else {
        crc = crc << 1;
      }
    }
  }
  crc &= 0xFFFF;
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

function generatePixPayload({
  pixKey = "contatejeff@gmail.com",
  merchantName = "Plataforma de Tarefas",
  merchantCity = "Sao Paulo",
  amount = 10.00,
  txid = "***"
}: {
  pixKey?: string;
  merchantName?: string;
  merchantCity?: string;
  amount: number;
  txid?: string;
}) {
  const formatField = (id: string, value: string) => {
    const len = value.length.toString().padStart(2, '0');
    return `${id}${len}${value}`;
  };

  const gui = formatField("00", "br.gov.bcb.pix");
  const key = formatField("01", pixKey);
  const merchantAccountInfo = formatField("26", gui + key);

  const payloadFormat = formatField("00", "01");
  const initiationMethod = formatField("01", "12");
  const mcc = formatField("52", "0000");
  const currency = formatField("53", "986");
  const formattedAmount = formatField("54", amount.toFixed(2));
  const country = formatField("58", "BR");
  const name = formatField("59", merchantName);
  const city = formatField("60", merchantCity);
  const additionalData = formatField("62", formatField("05", txid));

  let payloadWithoutCrc = 
    payloadFormat +
    initiationMethod +
    merchantAccountInfo +
    mcc +
    currency +
    formattedAmount +
    country +
    name +
    city +
    additionalData +
    "6304";

  const crc = calculateCRC16(payloadWithoutCrc);
  return payloadWithoutCrc + crc;
}

